CREATE TABLE "better_supabase"."rule_defaults" (
  "key"          text                     NOT NULL,
  "block"        text                     NOT NULL,
  "subject_type" text                     NOT NULL,
  "trigger"      text                     NOT NULL,
  "name"         text                     NOT NULL,
  "description"  text,
  "conditions"   jsonb                    NOT NULL DEFAULT '{"id": "root", "type": "group", "rules": [], "combinator": "and"}'::jsonb,
  "actions"      jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "enabled"      boolean                  NOT NULL DEFAULT true,
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "rule_defaults_actions_check" CHECK ((jsonb_typeof(actions) = 'array'::text)),
  CONSTRAINT "rule_defaults_description_check" CHECK ((length(description) <= 2000)),
  CONSTRAINT "rule_defaults_key_check" CHECK (((length(key) <= 128) AND (key ~ '^[a-z][a-z0-9_]*([.][a-z0-9_]+)*$'::text))),
  CONSTRAINT "rule_defaults_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "rule_defaults_pkey" PRIMARY KEY (key),
  CONSTRAINT "rule_defaults_subject_type_check" CHECK ((subject_type ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
  CONSTRAINT "rule_defaults_trigger_check" CHECK (((length(trigger) <= 128) AND (trigger ~ '^[a-z][a-z0-9_]*([.:][a-z0-9_]+)*$'::text)))
);

